import { openai } from "../llm"; // juez: familia distinta a la del agente

type Verdict = { passa: boolean; motivo: string };

const RUBRICA = `Eres un juez binario.
Recibes (1) la pregunta, (2) el contexto recuperado, (3) la salida del agente y (4) el gabarito.
Responde SOLO un JSON con el formato {"passa": bool, "motivo": "<1 frase>"}.
Considera passa=true solo si la salida es fiel al gabarito Y no inventa información fuera del contexto.`;

export async function judge(input: string, contexto: string, output: string, gabarito: string): Promise<Verdict> {
  const user = `Pregunta: ${input}\nContexto: ${contexto}\nSalida: ${output}\nGabarito: ${gabarito}`;
  const resp = await openai.chat.completions.create({
    model: "gpt-4o-mini",
    response_format: { type: "json_object" },
    messages: [{ role: "system", content: RUBRICA }, { role: "user", content: user }],
  });
  return JSON.parse(resp.choices[0].message.content);
}
